//! The Frank Harmon sets' annotation, lifted from their PDFs (see tools/fha): each set's title block families, each
//! sheet's own title block values, and every page's notes (with their leaders), dimension strings and bubbles, in
//! paper mm from the sheet's lower left. Carried deflated; read once, on first use.

import { inflateBase64 } from "./inflate.js";

const FHA_AIA_Z = "";
const FHA_CACHE = {};
/** One set's data: { titleBlocks: {id: family}, sheets: {page: {number, name, scale, tb}}, pages: {page: {size, notes, dims, bubbles}} }. */
export function fhaPdf(set) {
  if (!FHA_CACHE[set]) FHA_CACHE[set] = JSON.parse(inflateBase64({ aia: FHA_AIA_Z }[set]));
  return FHA_CACHE[set];
}
